function rows(){const out=HR.slice();S.live.forEach(o=>{if(o.st==='rejected'||(o.st==='pending'&&!S.pend)||!N[o.node])return;const m=String(o.d).slice(0,7),ks=Object.entries(o.am||{}).filter(x=>+x[1]>0);(ks.length?ks:[['',o.a]]).forEach((x,i)=>out.push({src:'e',eid:o.id,ety:x[0],st:o.st,m,d:o.d,node:o.node,t:cty(x[0]),a:+x[1]||0,kg:i?0:+o.kg||0,cu:i?0:+o.cu||0,nw:i?0:+o.nw||0}))});return out}
