function perm(){return '<div class="p"><h2>جدول الصلاحيات</h2><p class="mut">كل صف عنصر. اضغط «تعديل» وحدد مين يدخل عليه البيانات ومين يراجع ويعتمد. الصلاحية على العنصر نفسه بس، مش بتشمل اللي تحته. العنصر اللي مالوش مراجع، الأدمن هو اللي يعتمده.</p><input id="pq" placeholder="ابحث باسم العنصر..." value="'+(S.pq||'')+'" style="width:100%"></div>'+(S.pe?pedit():'')+'<div id="pl">'+plist()+'</div>'}
function tgtTab(){const m=S.tgm||cm,k=mk6(m),rows=flatAll(),tyc=sel=>TY.map(t=>'<label><input type="checkbox" class="tgy" data-t="'+t.id+'"'+(sel.includes(t.id)?' checked':'')+'> '+t.n+'</label>').join('');
return '<div class="p"><h2>التارجت الشهري</h2><p class="mut">لكل اسم: اكتب الرقم، واختار هو <b>فلوس</b> ولا <b>كيلو</b>. لو كيلو اكتب <b>متوسط سعر الكيلو</b> عشان يتحوّل لفلوس. وتقدر تحدد التارجت على نوع معيّن (بونات بس، أو جملة بس، أو الاتنين) من «الأنواع»، أو سيبها «كل الأنواع». الخانة الفاضية معناها ياخد تارجت آخر شهر محدد قبله.</p><div class="fb"><div><label>الشهر</label><input type="month" id="tgm" value="'+m+'"></div><div><label>بحث</label><input id="tgq" placeholder="ابحث..."></div></div><p><button class="btn" data-a="tgs">حفظ التارجت</button> <button class="btn s" data-a="tgc">انسخ من الشهر اللي قبله</button></p>'
+rows.map(x=>{const n=N[x.id],t=n.tm||{},own=t[k]!==undefined,c=tgt0(n,m),o=own?c:{v:'',u:'m',p:'',ty:[]},ph=own?'':(c.money>0?(c.u==='k'?f(c.v)+' كجم':f(c.v)):(n.kids.length?Tm(x.id,m):'')),car=own||!(c.money>0)?'':'موروث: '+(c.u==='k'?f(c.v)+' كجم × '+f(c.p)+' = '+f(c.money):f(c.v))+(c.ty.length?' ('+c.ty.map(tn).join('، ')+')':'');
return '<div class="tgr" data-q="'+nz(lbl(x.id))+'" data-id="'+x.id+'"><b style="padding-right:'+x.d*14+'px">'+n.name+' <span class="tag">'+n.type+'</span>'+(car?' <span class="mut">'+car+'</span>':'')+'</b><input type="number" min="0" class="tgi" value="'+(own?o.v:'')+'" placeholder="'+ph+'"><select class="tgu"><option value="m"'+(o.u==='k'?'':' selected')+'>فلوس</option><option value="k"'+(o.u==='k'?' selected':'')+'>كيلو</option></select><input type="number" min="0" class="tgp" placeholder="سعر الكيلو" value="'+(own&&o.u==='k'?o.p:'')+'" style="'+(own&&o.u==='k'?'':'display:none')+'"><details class="tgt"><summary>'+(own&&o.ty.length?o.ty.map(tn).join('، '):'كل الأنواع')+'</summary><div class="chk" style="flex-direction:column">'+tyc(own?o.ty:[])+'</div></details></div>'}).join('')+'</div>'}
const canE=id=>ME.perms.admin||(ME.editNodes||[]).includes(id);
function editTab(){fInit();const F=S.f,R=rows().filter(r=>canE(r.node)&&okN(r.node)&&(!F.t.length||F.t.includes(r.t))&&inR(r,F.from,F.to)).sort((a,b)=>String(b.d||b.m+'-99').localeCompare(String(a.d||a.m+'-99'))),L=R.slice(0,150);S.erows=L;
const to=(sel,bl)=>(bl?'<option value=""'+(sel===''?' selected':'')+'>غير مفصّل</option>':'')+TY.map(t=>'<option value="'+t.id+'"'+(t.id===sel?' selected':'')+'>'+t.n+'</option>').join('');
return filtUI()+'<div class="p"><h2>تعديل الأرقام</h2><p class="mut">كل صف رقم. غيّر النوع أو المبلغ أو التاريخ واضغط «حفظ». ولتغيير نوع كذا رقم مرة واحدة: حددهم واختار النوع الجديد من فوق. «شهري» معناها رقم قديم متسجل على الشهر كله.</p><div class="fb"><label style="flex:0 0 auto;display:flex;gap:6px;align-items:center"><input type="checkbox" class="esa"> تحديد الكل</label><select id="ebt" style="flex:1">'+to('',true)+'</select><button class="btn" data-a="eb">غيّر النوع للمحدد</button></div>'
+(L.length?'<div class="tw"><table><tr><th></th><th>النوع</th><th>المبلغ</th><th>التاريخ</th><th>الاسم</th><th>الحالة</th><th></th></tr>'+L.map((r,i)=>'<tr><td><input type="checkbox" class="esl" data-i="'+i+'"></td><td><select id="ety'+i+'">'+to(r.t,r.src==='h'||r.t==='')+'</select></td><td><input type="number" min="0" id="eam'+i+'" value="'+r.a+'" style="width:110px"></td><td>'+(r.src==='h'?'<input type="month" id="edt'+i+'" value="'+r.m+'"> <span class="tag">شهري</span>':'<input type="date" id="edt'+i+'" value="'+r.d+'">')+'</td><td class="mut">'+lbl(r.node)+'</td><td><span class="tag '+(r.st||'approved')+'">'+ST[r.st||'approved']+'</span></td><td class="n"><button class="btn s" data-es="'+i+'">حفظ</button> <button class="btn s r" data-ex="'+i+'">إلغاء الرقم</button></td></tr>').join('')+'</table></div>'+(R.length>150?'<p class="mut">عرضت أول 150 من '+R.length+'. ضيّق الفلاتر.</p>':''):'<div class="mut">لا توجد أرقام بالفلاتر دي.</div>')+'</div>'}
function adm(){return '<div class="chips">'+[['tree','الهيكل'],['edit','تعديل الأرقام'],['tgt','التارجت'],['perm','جدول الصلاحيات'],['names','أسماء من جدول'],['paste','لصق من الإكسيل'],['users','المستخدمون'],['types','نوعيات التحصيل'],['data','البيانات']].map(x=>'<button data-as="'+x[0]+'" class="'+(S.as===x[0]?'on':'')+'">'+x[1]+'</button>').join('')+'</div>'+({tree,edit:editTab,tgt:tgtTab,perm,names,paste,users,types,data}[S.as])()}
const addM=(m,k)=>{let y=+m.slice(0,4),mo=+m.slice(5,7)+k;y+=Math.floor((mo-1)/12);mo=((mo-1)%12+12)%12+1;return y+'-'+String(mo).padStart(2,'0')};
const mrange=(a,b)=>{const o=[];let m=a;while(m<=b&&o.length<72){o.push(m);m=addM(m,1)}return o};
const sh=v=>v>=1e6?(v/1e6).toFixed(1)+'م':v>=1e3?Math.round(v/1e3)+'ك':String(Math.round(v));
const sumA=R=>R.reduce((a,r)=>a+r.a,0);
const PAL=['#118DFF','#12239E','#E66C37','#F2C80F','#6B007B','#E044A7','#744EC2','#D64550','#8E7F5A'];
const nice=v=>{if(!(v>0))return 1;const p=Math.pow(10,Math.floor(Math.log10(v))),k=v/p;return (k<=1?1:k<=2?2:k<=2.5?2.5:k<=5?5:10)*p};
const dlt=(c,p)=>p?'<span class="'+(c>=p?'pos':'neg')+'">'+(c>=p?'▲ ':'▼ ')+Math.abs((c/p-1)*100).toFixed(1)+'%</span>':'<span class="mut">—</span>';
const iso=dt=>dt.toISOString().slice(0,10),fd=m=>m+'-01',ld=m=>iso(new Date(Date.UTC(+m.slice(0,4),+m.slice(5,7),0)));
const addD=(x,k)=>{const d=new Date(x+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+k);return iso(d)},addY=(x,k)=>{const d=new Date(x+'T00:00:00Z');d.setUTCFullYear(d.getUTCFullYear()+k);return iso(d)},dd2=(a,b)=>Math.round((new Date(b)-new Date(a))/864e5)+1;
const inR=(r,a,b)=>r.d?(r.d>=a&&r.d<=b):(fd(r.m)>=a&&ld(r.m)<=b);
function okN(id){const n=N[id];if(!n||!V.has(id))return false;const sel=[...S.f.path].reverse().find(Boolean);return !sel||n.path.includes(sel)}
function fInit(){const ms=months();if(!S.f)S.f={from:'',to:'',path:[],t:[]};const F=S.f;if(!F.path)F.path=[];if(!F.t)F.t=[];if(!F.touched||!F.from){const m=ms[0]||cm;F.from=fd(m);F.to=ld(m)}}
const qr=k=>{const t=td,mt=cm;if(k==='today')return [t,t];if(k==='7')return [addD(t,-6),t];if(k==='m')return [fd(mt),ld(mt)];if(k==='pm'){const p=addM(mt,-1);return [fd(p),ld(p)]}if(k==='3m')return [fd(addM(mt,-2)),ld(mt)];if(k==='y')return [mt.slice(0,4)+'-01-01',mt.slice(0,4)+'-12-31'];const ms=months();return [fd(ms[ms.length-1]||mt),ld(ms[0]||mt)]};
function casF(path){let h='',par='';for(let k=0;k<=path.length;k++){const opts=par?kv(par):top();if(!opts.length)break;const sel=path[k]||'';h+='<div><label>'+N[opts[0]].type+'</label><select class="fc" data-k="'+k+'"><option value="">— الكل —</option>'+opts.map(i=>'<option value="'+i+'"'+(i===sel?' selected':'')+'>'+N[i].name+'</option>').join('')+'</select></div>';if(!sel)break;par=sel}return h}
