+labels.map((l,i)=>{const x=46+i*46,h=base-y(vals[i]);return '<rect x="'+(x+4)+'" y="'+y(vals[i])+'" width="30" height="'+Math.max(0,h)+'" rx="3" fill="var(--g)" opacity="'+(hl[i]?1:.38)+'"><title>'+l+': '+f(vals[i])+'</title></rect>'+(vals[i]?'<text x="'+(x+19)+'" y="'+(+y(vals[i])-4)+'" text-anchor="middle" font-size="9" font-weight="700" fill="var(--ink)">'+sh(vals[i])+'</text>':'')+'<text x="'+(x+19)+'" y="152" text-anchor="middle" font-size="10" fill="var(--mut)">'+l.slice(5)+'/'+l.slice(2,4)+'</text>'}).join('')
